import struct
from cryptography import x509
from binascii import unhexlify
from pathlib import Path


def parse_trustlist(data):
    #data = bytes.fromhex(hex_string)
    offset = 0

    def read_i32():
        nonlocal offset
        val = struct.unpack_from("<i", data, offset)[0]
        offset += 4
        return val

    def read_bytes():
        nonlocal offset
        length = read_i32()
        if length < 0:
            return None
        val = data[offset:offset+length]
        offset += length
        return val

    def read_array():
        count = read_i32()
        if count < 0:
            return []
        return [read_bytes() for _ in range(count)]

    result = {}

    result["specifiedLists"] = read_i32()
    result["trustedCertificates"] = read_array()
    result["trustedCrls"] = read_array()
    result["issuerCertificates"] = read_array()
    result["issuerCrls"] = read_array()

    return result


def encode_bytes(b):
    if b is None:
        return struct.pack("<i", -1)
    return struct.pack("<i", len(b)) + b

def encode_array(arr):
    if arr is None:
        return struct.pack("<i", -1)

    out = struct.pack("<i", len(arr))
    for item in arr:
        out += encode_bytes(item)
    return out


def build_trustlist_bytes(tl):
    out = b""
    out += struct.pack("<i", tl["specifiedLists"])
    out += encode_array(tl.get("trustedCertificates"))
    out += encode_array(tl.get("trustedCrls"))
    out += encode_array(tl.get("issuerCertificates"))
    out += encode_array(tl.get("issuerCrls"))

    return out

def add_crl_to_trustlist(tl, crl_bytes):
    tl["specifiedLists"] |= 0x02

    crls = tl.get("trustedCrls") or []
    crls.append(crl_bytes)
    tl["trustedCrls"] = crls

    return tl

hex_string = ""
raw = bytes.fromhex(hex_string)
tl = parse_trustlist(raw)
crl = Path("ca4/gds_ca_crl.der").read_bytes()
tl = add_crl_to_trustlist(tl, crl)

new_blob = build_trustlist_bytes(tl)
Path("trustlist.bin").write_bytes(new_blob)

print(tl)

